import{_ as t,I as e,g as r,j as o}from"./chunks/framework.CjoWWfVe.js";const _=JSON.parse('{"title":"Маркетплейс модулей (Add-ons)","description":"Подключение расширений, кастомизация программы под конкретное ремесло и управление платными/бесплатными модулями.","frontmatter":{"title":"Маркетплейс модулей (Add-ons)","description":"Подключение расширений, кастомизация программы под конкретное ремесло и управление платными/бесплатными модулями.","order":16},"headers":[],"relativePath":"ru/docs/spaces/marketplace.md","filePath":"ru/docs/spaces/marketplace.md"}'),s={name:"ru/docs/spaces/marketplace.md"};function l(i,a,n,p,c,d){return e(),r("div",null,[...a[0]||(a[0]=[o('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🧩-маркетплеис-модулеи-экосистема-расширении" tabindex="-1">🧩 Маркетплейс модулей (Экосистема расширений) <a class="header-anchor" href="#🧩-маркетплеис-модулеи-экосистема-расширении" aria-label="Permalink to &quot;🧩 Маркетплейс модулей (Экосистема расширений)&quot;">​</a></h1><p>Профессия ремесленника слишком многогранна, чтобы уместить её в один универсальный интерфейс. То, что идеально подходит кожевеннику (лекала, площадь кроя), будет абсолютно бесполезно мастеру по ремонту часов или гончару, только перегружая программу лишними кнопками.</p><p>Для решения этой проблемы ОмниКрафт ЕРП использует архитектуру <strong>Сквозных модулей (Add-ons)</strong>. Базовое ядро программы остается легким и быстрым, а специфические нишевые функции вы можете подключать самостоятельно через встроенный <strong>Маркетплейс</strong>.</p><hr><h2 id="🛒-как-работает-маркетплеис" tabindex="-1">🛒 Как работает Маркетплейс <a class="header-anchor" href="#🛒-как-работает-маркетплеис" aria-label="Permalink to &quot;🛒 Как работает Маркетплейс&quot;">​</a></h2><p>В правой выдвижной панели (Drawer) в разделе «Сквозные модули» находится кнопка <strong>Маркетплейс модулей</strong>. При её нажатии программа связывается с сервером и загружает актуальный каталог доступных расширений.</p><h3 id="_1-подключение-бесплатных-модулеи" tabindex="-1">1. Подключение бесплатных модулей <a class="header-anchor" href="#_1-подключение-бесплатных-модулеи" aria-label="Permalink to &quot;1. Подключение бесплатных модулей&quot;">​</a></h3><p>Некоторые системные модули (например, <em>«Амбассадор»</em>) распространяются абсолютно бесплатно. Чтобы начать ими пользоваться:</p><ol><li>Откройте Маркетплейс.</li><li>Найдите нужный модуль и нажмите кнопку <strong>«Подключить бесплатно»</strong>.</li><li>Программа мгновенно обновит ваш лицензионный ключ и разблокирует модуль. Никакого скачивания файлов, установки или перезагрузки программы не требуется — модуль сразу появится в боковом меню!</li></ol><h3 id="_2-покупка-платных-модулеи" tabindex="-1">2. Покупка платных модулей <a class="header-anchor" href="#_2-покупка-платных-модулеи" aria-label="Permalink to &quot;2. Покупка платных модулей&quot;">​</a></h3><p>Узкоспециализированные профессиональные модули оплачиваются единоразово. Вы платите только за те инструменты, которые реально используете в своей работе.</p><ol><li>В карточке платного модуля нажмите кнопку <strong>«Купить за X ₽»</strong>.</li><li>Откроется окно безопасной онлайн-оплаты в браузере.</li><li>Сразу после успешной оплаты модуль автоматически привяжется к вашему лицензионному ключу, и вы сможете начать работу.</li></ol><div class="tip custom-block"><p class="custom-block-title">Техническая магия (Нулевой оверхед)</p><p>Вам не нужно переживать, что установка десятков модулей замедлит работу вашего компьютера. Все модули физически вшиты в исходный код программы, но они используют архитектуру «ленивой загрузки» (Lazy Loading). Модуль не потребляет ни мегабайта оперативной памяти до тех пор, пока вы на него не кликнете.</p></div><hr><h2 id="🔄-сквозная-природа-модулеи" tabindex="-1">🔄 Сквозная природа модулей <a class="header-anchor" href="#🔄-сквозная-природа-модулеи" aria-label="Permalink to &quot;🔄 Сквозная природа модулей&quot;">​</a></h2><p>Почему модули называются «сквозными»? В отличие от складов сырья или чеков, которые жестко привязаны к конкретному бизнесу (в ПРО-режиме), сквозные модули работают <strong>поверх всех ваших рабочих пространств</strong>.</p><p>Если вы купили модуль «Выкройки», вы сможете пользоваться единой базой своих чертежей и лекал независимо от того, в каком из ваших бизнес-пространств вы находитесь в данный момент.</p>',18)])])}const m=t(s,[["render",l]]);export{_ as __pageData,m as default};
